#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
//
// mutants — мутационные пробы задачи: каждый мутант ломает одну строку прод-кода в своей копии
// рабочего дерева и гоняет тесты, которые обязаны это заметить. Настройки репозитория —
// tests.repos.<репо>.mutate в .claude/workspace.json, слоты машины — общие с parallel-tests.mjs.
//
//   node .claude/bin/mutants.mjs <мутанты.json>                   # прогнать изменившиеся
//   node .claude/bin/mutants.mjs <мутанты.json> --task SHOP-12    # база — worktrees/SHOP-12/<репо>
//   node .claude/bin/mutants.mjs <мутанты.json> --only M3,M7      # только названные
//   node .claude/bin/mutants.mjs <мутанты.json> --force           # без кеша
//   node .claude/bin/mutants.mjs <мутанты.json> --dry-run         # что пойдёт, что из кеша
//   node .claude/bin/mutants.mjs <мутанты.json> --workers 4       # не больше 4 слотов
//   node .claude/bin/mutants.mjs --clean                          # убрать копии деревьев
//   node .claude/bin/mutants.mjs --clean --dry-run                # какие копии убрал бы, какие заняты
//
// Копию, чей слот держит идущий прогон mutants, --clean пропускает. Его же зовёт
// .claude/bin/workspace-clean cache вместе с уборкой остального кеша.
//
// Файл мутантов лежит во временном каталоге роли, а не в memory/tasks/<КОД>/: в память идёт
// только таблица, которую печатает инструмент. Формат:
//
//   { "repo": "<репо>", "task": "<КОД>", "filter": "<аргументы фильтра по умолчанию>",
//     "tests": ["tests/Unit/XTest.php:42"],
//     "mutants": [ { "id": "M1", "criterion": "<критерий приёмки или метка находки>",
//                    "file": "<путь от корня репозитория>", "find": "<точная строка>",
//                    "replace": "<на что>", "what": "<что сломано, одной фразой>",
//                    "filter": "<аргументы фильтра>", "tests": ["<файл:строка>"] } ] }
//
// repo, task, filter и tests верхнего уровня — значения по умолчанию для каждого мутанта.
// find должна встречаться в файле ровно один раз — иначе «ошибка применения», а не прогон:
// мутант, попавший не в ту строку, мерит не тот код. filter подставляется в {filter} команды
// mutate.command; остановка на первом падении — в самой команде (phpunit --stop-on-failure,
// jest --bail). tests — тестовые файлы фильтра: их содержимое входит в хеш мутанта.
//
// Как идёт прогон:
// - копия на слот — git worktree в .claude/.cache/mutants/<репо>-s<слот>, на коммите базы плюс
//   снимок её незакоммиченных правок; mutate.link — каталоги базы ссылкой (vendor,
//   node_modules), mutate.copy — файлы копией (env); переменные воркера и prepare — те же,
//   что у parallel-tests, с {dir} копии и {i} её слота;
//   vendor composer — настоящий каталог: composer/, bin/ и autoload.php копией, пакеты
//   ссылками, иначе автозагрузчик нашёл бы классы приложения в базе, а не в копии;
// - контроль: на каждую пару «репозиторий, фильтр» — нулевой мутант без замены; он обязан
//   быть зелёным, иначе мутанты этого фильтра недействительны — проба мерила бы себя;
// - проверка копии (copycheck): на каждый мутируемый файл — тот же фильтр с этим файлом,
//   опустошённым в копии; он обязан покраснеть, иначе тест не видит файл копии, и мутанты
//   в нём недействительны, а не «выжили»;
// - на мутант: замена → mutate.check с {file}, если задан (синтаксис файла) → команда с
//   фильтром → откат файла → копия обязана быть чистой (git status --porcelain пуст);
// - кеш: хеш определения мутанта, команды, мутируемого файла и тестовых файлов; совпал
//   с прошлым прогоном — результат берётся из <мутанты>.cache.json рядом с файлом мутантов.
//
// Вывод: строка на мутант по ходу, затем таблица в форме таблицы мутаций test-cases.md
// (она же — файлом <мутанты>.table.md), TOTAL mutants=… killed=… survived=… и последней
// строкой CODE=: 0 — все мутанты убиты, 1 — выжившие, ошибки применения, красный контроль
// или неполный прогон, 2 — ошибка настроек или файла мутантов. Логи — <мутанты>.runs/.
//
// Мутации, которые ловит браузерный сценарий, эта версия не гоняет: dev-сервер обслуживает
// своё рабочее дерево, а не копию мутанта.

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { findRoot, loadWorkspace, PROJECTS_DIR, WORKTREES_DIR, SAFE_NAME } from './lib/workspace.mjs';
import {
  UserError, say, fail, slotLimit, locked, scan, acquire, release, killChildren,
  installStopHandlers, run as runIn, subst, TIMEOUT_CODE,
} from './lib/slots.mjs';

const self = fileURLToPath(import.meta.url);
const argv = process.argv.slice(2);

if (argv.includes('-h') || argv.includes('--help')) {
  const lines = fs.readFileSync(self, 'utf8').split('\n').slice(2);
  const end = lines.findIndex((l) => !l.startsWith('//'));
  process.stdout.write(lines.slice(0, end).map((l) => l.replace(/^\/\/ ?/, '')).join('\n') + '\n');
  process.exit(0);
}

const run = (command, o) => runIn(command, { ...o, tool: 'mutants' });
const opts = { input: null, task: null, workers: null, only: null, force: false, dryRun: false, clean: false };

function parseArgs() {
  for (let a = 0; a < argv.length; a++) {
    const arg = argv[a];
    const val = () => {
      const v = argv[++a];
      if (v === undefined || v.startsWith('--')) fail(`${arg}: нет значения`);
      return v;
    };
    if (arg === '--task') opts.task = val();
    else if (arg === '--workers') {
      const n = Number(val());
      if (!Number.isInteger(n) || n < 1) fail('--workers: ждётся целое больше нуля');
      opts.workers = n;
    } else if (arg === '--only') opts.only = new Set(val().split(',').map((s) => s.trim()).filter(Boolean));
    else if (arg === '--force') opts.force = true;
    else if (arg === '--dry-run') opts.dryRun = true;
    else if (arg === '--clean') opts.clean = true;
    else if (arg.startsWith('--')) fail(`неизвестный аргумент ${arg} — см. --help`);
    else if (opts.input === null) opts.input = arg;
    else fail(`лишний аргумент ${arg}`);
  }
  if (!opts.clean && !opts.input) fail('нет файла мутантов — см. --help');
}

installStopHandlers();

// ---------- git ----------

function git(cwd, args, { env, allowFail, input } = {}) {
  const r = spawnSync('git', ['-C', cwd, ...args], { encoding: 'utf8', env: env ?? process.env, input, windowsHide: true, maxBuffer: 64 << 20 });
  if (r.status !== 0 && !allowFail) fail(`git -C ${cwd} ${args.join(' ')}: ${(r.stderr || r.stdout || '').trim()}`);
  return allowFail ? r : r.stdout;
}

// Ссылки и копии файлов в копии дерева — не изменения: шаблон «vendor/» в .gitignore симлинк
// не ловит (на Linux и macOS это не каталог), поэтому они исключаются из status, add и clean явно.
const outside = (own) => ['--', '.', ...own.map((p) => `:(exclude)${p}`)];
const cleanCopy = (copy, own) => git(copy, ['clean', '-fdq', ...own.flatMap((p) => ['-e', `/${p}`])]);

// Пути из porcelain -z: «XY путь\0», у переименования за ним — старый путь отдельной записью.
function dirtyPaths(dir, own = []) {
  const out = git(dir, ['status', '--porcelain=v1', '-z', '-uall', ...outside(own)]);
  const parts = out.split('\0').filter(Boolean);
  const paths = [];
  for (let k = 0; k < parts.length; k++) {
    const xy = parts[k].slice(0, 2);
    paths.push(parts[k].slice(3));
    if (xy[0] === 'R' || xy[0] === 'C') paths.push(parts[++k]);
  }
  return paths;
}

const sameDir = (a, b) => {
  const n = (p) => path.resolve(p).replace(/\\/g, '/').replace(/\/+$/, '');
  return process.platform === 'win32' ? n(a).toLowerCase() === n(b).toLowerCase() : n(a) === n(b);
};

// ---------- копии деревьев ----------

// Путь в выводе — от корня workspace; файл мутантов лежит во временном каталоге роли вне его,
// и путь туда — абсолютный, а не цепочка «../».
const shown = (root, p) => {
  const r = path.relative(root, p);
  return (r.startsWith('..') || path.isAbsolute(r) ? path.resolve(p) : r).replace(/\\/g, '/');
};

const COPIES = (root) => path.join(root, '.claude', '.cache', 'mutants');

// Ссылки (junction на Windows) убираются до удаления копии: удаление дерева, прошедшее
// по ссылке, снесло бы vendor или node_modules самой базы.
function unlinkLinks(dir) {
  let entries = [];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    if (e.name === '.git') continue;
    const p = path.join(dir, e.name);
    let st;
    try { st = fs.lstatSync(p); } catch { continue; }
    if (st.isSymbolicLink()) fs.unlinkSync(p);
    else if (st.isDirectory()) unlinkLinks(p);
  }
}

// vendor composer ссылкой целиком прячет копию от тестов: автозагрузчик считает корень
// проекта от реального пути vendor/composer ($baseDir = dirname($vendorDir), $vendorDir =
// dirname(__DIR__)), и классы приложения грузятся из базы, а не из копии. Прокси vendor/bin
// так же считают autoload.php от своего __DIR__. Поэтому vendor копии — настоящий каталог:
// composer/, bin/ и файлы верхнего уровня — копией (небольшие), пакеты — ссылками на базу.
const isComposerVendor = (dir) => fs.existsSync(path.join(dir, 'autoload.php')) && fs.existsSync(path.join(dir, 'composer'));
const COMPOSER_COPIED = new Set(['composer', 'bin']);

function linkComposerVendor(target, dest) {
  fs.mkdirSync(dest);
  for (const e of fs.readdirSync(target, { withFileTypes: true })) {
    const from = path.join(target, e.name);
    const to = path.join(dest, e.name);
    if (COMPOSER_COPIED.has(e.name)) fs.cpSync(from, to, { recursive: true, verbatimSymlinks: true });
    else if (fs.statSync(from).isDirectory()) fs.symlinkSync(from, to, 'junction');
    else fs.copyFileSync(from, to);
  }
}

function removeCopy(copy) {
  unlinkLinks(copy);
  const r = git(copy, ['rev-parse', '--path-format=absolute', '--git-common-dir'], { allowFail: true });
  if (r.status === 0) spawnSync('git', ['--git-dir', r.stdout.trim(), 'worktree', 'remove', '--force', copy], { windowsHide: true });
  fs.rmSync(copy, { recursive: true, force: true });
}

async function clean(root) {
  const dir = COPIES(root);
  const held = await locked(() => scan({ clean: false }));
  let removed = 0;
  let names = [];
  try { names = fs.readdirSync(dir); } catch { /* копий нет */ }
  for (const name of names) {
    const m = name.match(/-s(\d+)$/);
    if (m && held.has(Number(m[1])) && held.get(Number(m[1])).tool === 'mutants') { say(`занята: ${name} — слот держит pid ${held.get(Number(m[1])).pid}`); continue; }
    if (opts.dryRun) say(`убрал бы: ${name}`);
    else { removeCopy(path.join(dir, name)); say(`убрана: ${name}`); }
    removed++;
  }
  say(`копий ${opts.dryRun ? 'убрал бы' : 'убрано'}: ${removed}`);
}

function prepareCopy({ root, repo, base, slot, cfg }) {
  const copy = path.join(COPIES(root), `${repo}-s${slot}`);
  const own = [...cfg.mutate.link, ...cfg.mutate.copy];
  const head = git(base, ['rev-parse', 'HEAD']).trim();
  if (fs.existsSync(copy)) {
    const mine = git(copy, ['rev-parse', '--path-format=absolute', '--git-common-dir'], { allowFail: true });
    const theirs = git(base, ['rev-parse', '--path-format=absolute', '--git-common-dir']).trim();
    if (mine.status !== 0 || !sameDir(mine.stdout.trim(), theirs)) fail(`${copy}: не копия ${repo} — node .claude/bin/mutants.mjs --clean`);
    git(copy, ['checkout', '-q', '--detach', '--force', head]);
    cleanCopy(copy, own);
  } else {
    fs.mkdirSync(path.dirname(copy), { recursive: true });
    git(base, ['worktree', 'add', '-q', '--detach', copy, head]);
  }
  for (const p of cfg.mutate.link) {
    const target = path.join(base, p);
    const dest = path.join(copy, p);
    let st = null;
    try { st = fs.statSync(target); } catch { /* нет */ }
    if (!st?.isDirectory()) fail(`${repo}: mutate.link «${p}» — в ${base} нет такого каталога`);
    if (git(base, ['ls-files', '--', p]).trim()) fail(`${repo}: mutate.link «${p}» отслеживается git — копия дерева получает его и так`);
    // Прошлый прогон оставил ссылку или каталог vendor — сначала снимаются ссылки внутри,
    // потом удаляется остальное: удаление, прошедшее по ссылке, снесло бы каталог базы.
    let cur = null;
    try { cur = fs.lstatSync(dest); } catch { /* ещё нет */ }
    if (cur?.isSymbolicLink()) fs.unlinkSync(dest);
    else if (cur) { unlinkLinks(dest); fs.rmSync(dest, { recursive: true, force: true }); }
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    if (isComposerVendor(target)) linkComposerVendor(target, dest);
    else fs.symlinkSync(target, dest, 'junction');
  }
  for (const p of cfg.mutate.copy) {
    const src = path.join(base, p);
    if (!fs.existsSync(src)) fail(`${repo}: mutate.copy «${p}» — в ${base} такого файла нет`);
    if (git(base, ['ls-files', '--error-unmatch', '--', p], { allowFail: true }).status === 0) fail(`${repo}: mutate.copy «${p}» отслеживается git — копия дерева получает его и так`);
    fs.mkdirSync(path.dirname(path.join(copy, p)), { recursive: true });
    fs.copyFileSync(src, path.join(copy, p));
  }
  // Незакоммиченные правки базы (тесты задачи часто ещё не в коммите) — снимком в копию:
  // мутант мерит то дерево, которое видит роль, а чистота копии сверяется с этим снимком.
  const dirty = dirtyPaths(base, own);
  for (const p of dirty) {
    const src = path.join(base, p);
    const dest = path.join(copy, p);
    let st = null;
    try { st = fs.statSync(src); } catch { /* удалён в базе */ }
    if (st?.isFile()) { fs.mkdirSync(path.dirname(dest), { recursive: true }); fs.copyFileSync(src, dest); }
    else if (!st) fs.rmSync(dest, { force: true });
  }
  if (dirty.length) {
    git(copy, ['add', '-A', '--pathspec-from-file=-', '--pathspec-file-nul'], { input: dirty.join('\0') });
    const tree = git(copy, ['write-tree']).trim();
    const who = { GIT_AUTHOR_NAME: 'beerpowers', GIT_AUTHOR_EMAIL: 'mutants@localhost', GIT_COMMITTER_NAME: 'beerpowers', GIT_COMMITTER_EMAIL: 'mutants@localhost' };
    const commit = git(copy, ['commit-tree', tree, '-p', 'HEAD', '-m', 'mutants: снимок рабочего дерева базы'], { env: { ...process.env, ...who } }).trim();
    git(copy, ['update-ref', '--no-deref', 'HEAD', commit]);
  }
  const left = dirtyPaths(copy, own);
  if (left.length) fail(`${repo}: копия после снимка не чистая: ${left.slice(0, 5).join(', ')}`);
  return copy;
}

// ---------- файл мутантов ----------

const sha = (...parts) => {
  const h = crypto.createHash('sha256');
  for (const p of parts) h.update(typeof p === 'string' ? p : JSON.stringify(p)).update('\0');
  return h.digest('hex').slice(0, 24);
};
const count = (s, sub) => (sub === '' ? 0 : s.split(sub).length - 1);
const cell = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');

function loadMutants(file, ws, root) {
  let doc;
  try { doc = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { fail(`${file}: ${e.code === 'ENOENT' ? 'файла нет' : `не JSON — ${e.message}`}`); }
  if (!doc || typeof doc !== 'object' || !Array.isArray(doc.mutants) || doc.mutants.length === 0) fail(`${file}: ждётся объект с непустым массивом mutants`);
  const task = opts.task ?? doc.task ?? null;
  if (task !== null && !SAFE_NAME.test(task)) fail(`task: «${task}» — не код задачи`);
  const ids = new Set();
  const bases = new Map();
  const list = doc.mutants.map((m, k) => {
    const where = `mutants[${k}]`;
    if (!m || typeof m !== 'object') fail(`${where}: ждётся объект`);
    const id = m.id;
    if (typeof id !== 'string' || !/^[A-Za-z0-9_.-]+$/.test(id)) fail(`${where}.id: ждётся метка вида M3`);
    if (ids.has(id)) fail(`${where}: id «${id}» повторяется`);
    ids.add(id);
    const repo = m.repo ?? doc.repo;
    if (typeof repo !== 'string') fail(`${id}: нет repo — ни у мутанта, ни сверху`);
    const cfg = ws.tests.repos[repo];
    if (!cfg) fail(`${id}: у «${repo}» нет записи tests.repos в .claude/workspace.json`);
    if (!cfg.mutate) fail(`${id}: у «${repo}» нет tests.repos.${repo}.mutate — команда мутанта, справка — reference/mutants.md плагина`);
    for (const k of ['file', 'find', 'replace']) if (typeof m[k] !== 'string') fail(`${id}.${k}: ждётся строка`);
    const filter = m.filter ?? doc.filter;
    if (typeof filter !== 'string' || !filter.trim()) fail(`${id}: нет filter — ни у мутанта, ни сверху`);
    const tests = m.tests ?? doc.tests ?? [];
    if (!Array.isArray(tests) || tests.length === 0 || tests.some((t) => typeof t !== 'string')) fail(`${id}: tests — непустой массив тестовых файлов фильтра`);
    if (!bases.has(repo)) {
      const rel = task ? `${WORKTREES_DIR}/${task}/${repo}` : `${PROJECTS_DIR}/${repo}`;
      if (!fs.existsSync(path.join(root, rel))) fail(`${repo}: нет каталога ${rel}`);
      bases.set(repo, { rel, abs: path.join(root, rel) });
    }
    return {
      id, repo, cfg, file: m.file.replace(/\\/g, '/'), find: m.find, replace: m.replace, filter,
      tests, testFiles: [...new Set(tests.map((t) => t.replace(/:\d+$/, '').replace(/\\/g, '/')))],
      what: m.what ?? '', criterion: m.criterion ?? '', base: bases.get(repo),
    };
  });
  return { list, bases };
}

// Ошибка применения ищется на базе, до слотов: копия — та же база, и мутант, который в неё
// не ложится, не стоит слота.
function inspect(m) {
  const read = (rel) => { try { return fs.readFileSync(path.join(m.base.abs, rel), 'utf8'); } catch { return null; } };
  const src = read(m.file);
  const tests = m.testFiles.map((t) => [t, read(t)]);
  let error = null;
  if (src === null) error = `файла ${m.file} нет`;
  else if (m.find === m.replace) error = 'find равна replace — мутант ничего не меняет';
  else if (count(src, m.find) !== 1) error = `find встречается в ${m.file} ${count(src, m.find)} раз, нужен ровно один`;
  else {
    const missing = tests.filter(([, c]) => c === null).map(([t]) => t);
    if (missing.length) error = `тестового файла нет: ${missing.join(', ')}`;
  }
  const mut = m.cfg.mutate;
  // Версия ключа растёт, когда меняется то, как копия собирается: результаты 2.4.0 с vendor
  // composer ссылкой целиком мерили код базы, а не копии, и из кеша возвращаться не должны.
  m.key = sha('mutant/2', { repo: m.repo, file: m.file, find: m.find, replace: m.replace, filter: m.filter, command: mut.command, check: mut.check, env: m.cfg.env }, src ?? '', ...tests.map(([t, c]) => `${t}\n${c ?? ''}`));
  m.error = error;
  m.src = src;
  m.testContents = tests;
}

// ---------- прогон ----------

async function main() {
  parseArgs();
  const root = findRoot(path.dirname(self));
  const ws = loadWorkspace(root);
  const fatals = ws.problems.filter((p) => p.fatal || p.testsFatal);
  if (fatals.length) fail(fatals.map((p) => `.claude/workspace.json: ${p.msg}`).join('\n'));
  const rel = (p) => shown(root, p);
  if (opts.clean) { await clean(root); return 0; }

  const input = path.resolve(opts.input);
  const stem = input.replace(/\.json$/i, '');
  const cacheFile = `${stem}.cache.json`;
  const runsDir = `${stem}.runs`;
  const { list } = loadMutants(input, ws, root);
  if (opts.only) {
    const unknown = [...opts.only].filter((id) => !list.some((m) => m.id === id));
    if (unknown.length) fail(`--only: нет мутантов ${unknown.join(', ')}`);
  }
  list.forEach(inspect);

  let cache = {};
  try { cache = JSON.parse(fs.readFileSync(cacheFile, 'utf8')); } catch { /* первый прогон */ }

  // Контроль — по паре «репозиторий, фильтр»: тот же фильтр без замены обязан быть зелёным.
  const groups = new Map();
  for (const m of list) {
    if (m.error) continue;
    const g = `${m.repo}\0${m.filter}`;
    if (!groups.has(g)) groups.set(g, { repo: m.repo, filter: m.filter, cfg: m.cfg, base: m.base, mutants: [] });
    groups.get(g).mutants.push(m);
  }
  // Проверка копии — по файлу каждой группы: тот же фильтр с опустошённым в копии файлом обязан
  // покраснеть. Зелёный значит, что тест читает этот файл не из копии (ссылка, автозагрузчик,
  // кеш сборки) или не читает вовсе, — и любой мутант в нём «выжил» бы, ничего не измерив.
  let cn = 0;
  let kn = 0;
  for (const g of groups.values()) {
    g.id = `control-${++cn}`;
    g.kind = 'control';
    const files = [...new Set(g.mutants.map((m) => m.file))].sort();
    const tests = [...new Map(g.mutants.flatMap((m) => m.testContents)).entries()].sort();
    g.key = sha('control/2', { repo: g.repo, filter: g.filter, command: g.cfg.mutate.command, env: g.cfg.env },
      ...files.map((f) => `${f}\n${g.mutants.find((m) => m.file === f).src}`), ...tests.map(([t, c]) => `${t}\n${c}`));
    g.label = g.mutants.map((m) => m.id).join(',');
    g.checks = files.map((f) => ({
      id: `copycheck-${++kn}`, kind: 'copycheck', repo: g.repo, cfg: g.cfg, base: g.base, filter: g.filter, file: f, group: g,
      label: `${f}: ${g.mutants.filter((m) => m.file === f).map((m) => m.id).join(',')}`, key: sha('copycheck/1', g.key, f),
    }));
  }

  const want = (m) => !opts.only || opts.only.has(m.id);
  for (const m of list) {
    m.kind = 'mutant';
    m.cached = !opts.force && !m.error && cache[m.key] ? cache[m.key] : null;
    m.todo = !m.error && !m.cached && want(m);
  }
  for (const g of groups.values()) {
    g.cached = !opts.force && cache[g.key] ? cache[g.key] : null;
    g.todo = g.mutants.some((m) => m.todo) || (!g.cached && g.mutants.some(want));
    for (const k of g.checks) {
      const of = g.mutants.filter((m) => m.file === k.file);
      k.cached = !opts.force && cache[k.key] ? cache[k.key] : null;
      k.todo = of.some((m) => m.todo) || (!k.cached && of.some(want));
    }
  }
  const controls = [...groups.values()].filter((g) => g.todo);
  const checks = [...groups.values()].flatMap((g) => g.checks).filter((k) => k.todo);
  const mutants = list.filter((m) => m.todo);

  if (opts.dryRun) {
    for (const g of groups.values()) {
      say(`${g.id} ${g.repo} filter=${g.filter} мутанты=${g.label} — ${g.todo ? 'прогон' : `кеш: ${g.cached.status}`}`);
      for (const k of g.checks) say(`${k.id} ${k.repo} ${k.label} — ${k.todo ? 'прогон' : `кеш: ${k.cached.status}`}`);
    }
    for (const m of list) say(`${m.id} ${m.repo} ${m.file} — ${m.error ? `ошибка применения: ${m.error}` : m.todo ? 'прогон' : m.cached ? `кеш: ${m.cached.status}` : 'не выбран'}`);
    say(`план: контролей ${controls.length}, проверок копии ${checks.length}, мутантов ${mutants.length}, из кеша ${list.filter((m) => m.cached).length}, ошибок применения ${list.filter((m) => m.error).length}`);
    return 0;
  }

  const t0 = Date.now();
  const jobs = controls.length + checks.length + mutants.length;
  if (jobs) {
    fs.mkdirSync(runsDir, { recursive: true });
    const limit = slotLimit(ws);
    const slots = await acquire(Math.min(limit.n, opts.workers ?? limit.n, Math.max(controls.length, checks.length, mutants.length)), limit, { tool: 'mutants', dir: rel(path.dirname(input)) }, 'mutants');
    say(`START mutants=${mutants.length} controls=${controls.length} copychecks=${checks.length} slots=${slots.join(',')}`);
    try {
      const all = [...controls, ...checks, ...mutants];
      const repos = [...new Set(all.map((x) => x.repo))];
      const copies = new Map();
      const prep = [];
      for (const slot of slots) {
        for (const repo of repos) {
          const any = all.find((x) => x.repo === repo);
          const copy = prepareCopy({ root, repo, base: any.base.abs, slot, cfg: any.cfg });
          copies.set(`${repo}\0${slot}`, copy);
          const vars = { i: slot, n: 1, slots: String(slot), repo, dir: copy, root, tmp: path.join(runsDir, `tmp-s${slot}`) };
          fs.mkdirSync(vars.tmp, { recursive: true });
          if (any.cfg.prepare) {
            prep.push((async () => {
              const log = fs.openSync(path.join(runsDir, `prepare-${repo}-s${slot}.log`), 'w');
              try {
                const code = await run(subst(any.cfg.prepare, vars), { cwd: copy, env: envOf(any.cfg, vars), log });
                if (code !== 0) fail(`подготовка ${repo} в слоте ${slot}: код ${code} — ${rel(path.join(runsDir, `prepare-${repo}-s${slot}.log`))}`);
              } finally { fs.closeSync(log); }
            })());
          }
        }
      }
      await Promise.all(prep);
      const ctx = { root, runsDir, copies, rel };
      await pool(slots, controls, (g, slot) => runJob(g, slot, ctx));
      for (const g of groups.values()) {
        const c = g.result ?? g.cached;
        if (c && c.status !== 'green') for (const m of g.mutants) { m.todo = false; m.invalid = `контроль ${g.id} красный — ${c.log ?? 'см. кеш'}`; }
      }
      await pool(slots, checks.filter((k) => !k.group.mutants.every((m) => m.invalid)), (k, slot) => runJob(k, slot, ctx));
      for (const g of groups.values()) {
        for (const k of g.checks) {
          const c = k.result ?? k.cached;
          if (!c || c.status === 'red') continue;
          for (const m of g.mutants) {
            if (m.file !== k.file || m.invalid) continue;
            m.todo = false;
            m.invalid = `тест не видит ${k.file} копии: фильтр зелёный и с пустым файлом (${k.id}) — ${c.log}`;
          }
        }
      }
      await pool(slots, mutants.filter((m) => m.todo), (m, slot) => runJob(m, slot, ctx));
    } finally {
      release(slots);
      for (const slot of slots) fs.rmSync(path.join(runsDir, `tmp-s${slot}`), { recursive: true, force: true });
    }
  }

  // Красный контроль не кешируется: причина бывает в окружении, и следующий прогон его повторит.
  // То же у проверки копии: кешируется только красная — копия видна тесту.
  for (const g of groups.values()) {
    if (g.result?.status === 'green') cache[g.key] = g.result;
    for (const k of g.checks) if (k.result?.status === 'red') cache[k.key] = k.result;
  }
  for (const m of list) if (m.result && ['killed', 'survived'].includes(m.result.status)) cache[m.key] = m.result;
  if (jobs) fs.writeFileSync(cacheFile, JSON.stringify(cache, null, 1));

  // ---------- таблица и итог ----------
  const ru = { killed: 'убит', survived: 'выжил' };
  const rows = [];
  const tally = { killed: 0, survived: 0, errors: 0, invalid: 0, cached: 0, skipped: 0 };
  for (const m of list) {
    const g = groups.get(`${m.repo}\0${m.filter}`);
    const control = g ? (g.result ?? g.cached) : null;
    const r = m.result ?? m.cached;
    let onBranch = '—';
    let onMutant = '—';
    let status;
    if (m.error) { status = `ошибка применения: ${m.error}`; tally.errors++; }
    else if (m.invalid) { status = `недействителен: ${m.invalid}`; tally.invalid++; onBranch = control?.status === 'green' ? 'зелёный' : 'красный'; }
    else if (!r) { status = 'не прогнан'; tally.skipped++; }
    else if (r.status === 'apply-error') { status = `ошибка применения: ${r.note}`; tally.errors++; }
    else {
      onBranch = control?.status === 'green' ? 'зелёный' : 'красный';
      onMutant = r.status === 'killed' ? 'красный' : 'зелёный';
      status = ru[r.status] + (r.timeout ? ' (таймаут)' : '') + (!m.result ? ' (кеш)' : '');
      tally[r.status]++;
      if (!m.result) tally.cached++;
    }
    rows.push(`| ${cell(m.criterion)} | ${m.tests.map((t) => `\`${cell(t)}\``).join(', ')} | \`${m.id}\` ${cell(m.what || `\`${m.find}\` → \`${m.replace}\``)} (\`${cell(m.file)}\`) | ${onBranch} | ${onMutant} | ${cell(status)} |`);
  }
  const table = ['| Критерий или находка | Тест | Мутация | На ветке | На мутанте | Статус |', '|---|---|---|---|---|---|', ...rows].join('\n');
  fs.writeFileSync(`${stem}.table.md`, table + '\n');
  say('');
  say(table);
  say('');
  const code = tally.survived || tally.errors || tally.invalid || tally.skipped ? 1 : 0;
  say(`TOTAL mutants=${list.length} killed=${tally.killed} survived=${tally.survived} errors=${tally.errors} invalid=${tally.invalid} skipped=${tally.skipped} cached=${tally.cached} time=${((Date.now() - t0) / 1000).toFixed(1)}s table=${rel(`${stem}.table.md`)}`);
  return code;
}

function envOf(cfg, vars) {
  const env = { ...process.env, BEERPOWERS_TEST_SLOT: String(vars.i), BEERPOWERS_TEST_SLOTS: String(vars.i) };
  for (const [k, v] of Object.entries(cfg.env)) env[k] = subst(v, vars);
  return env;
}

async function pool(slots, items, fn) {
  const queue = [...items];
  await Promise.all(slots.map(async (slot) => {
    for (let x = queue.shift(); x; x = queue.shift()) await fn(x, slot);
  }));
}

// Контроль, проверка копии и мутант идут одним путём: разница — только правка файла
// (никакой, пустой файл, замена find на replace).
async function runJob(job, slot, { root, runsDir, copies }) {
  const mutant = job.kind === 'mutant' ? job : null;
  const edited = job.kind === 'control' ? null : job.file;
  const repo = job.repo;
  const cfg = job.cfg;
  const copy = copies.get(`${repo}\0${slot}`);
  const logPath = path.join(runsDir, `${job.id}.log`);
  const log = fs.openSync(logPath, 'w');
  const vars = { i: slot, n: 1, slots: String(slot), repo, dir: copy, root, tmp: path.join(runsDir, `tmp-s${slot}`) };
  const env = envOf(cfg, vars);
  const t0 = Date.now();
  const logRel = shown(root, logPath);
  let result;
  try {
    fs.writeSync(log, `# ${job.id} ${repo} slot=${slot} copy=${copy}\n`);
    if (job.kind === 'copycheck') {
      fs.writeFileSync(path.join(copy, job.file), '');
      fs.writeSync(log, `# ${job.file}: опустошён в копии — фильтр обязан покраснеть\n`);
    }
    if (mutant) {
      const p = path.join(copy, mutant.file);
      const src = fs.readFileSync(p, 'utf8');
      if (count(src, mutant.find) !== 1) {
        result = { status: 'apply-error', note: `find встречается в копии ${count(src, mutant.find)} раз` };
      } else {
        fs.writeFileSync(p, src.replace(mutant.find, () => mutant.replace));
        fs.writeSync(log, `# ${mutant.file}: ${JSON.stringify(mutant.find)} → ${JSON.stringify(mutant.replace)}\n`);
        if (cfg.mutate.check && await run(subst(cfg.mutate.check, { ...vars, file: p }), { cwd: copy, env, log }) !== 0) {
          result = { status: 'apply-error', note: 'mutate.check не принял файл после замены' };
        }
      }
    }
    if (!result) {
      const code = await run(subst(cfg.mutate.command, { ...vars, filter: job.filter }), { cwd: copy, env, log, timeoutMs: cfg.mutate.timeout * 1000 });
      if (mutant) result = { status: code === 0 ? 'survived' : 'killed', timeout: code === TIMEOUT_CODE || undefined, code };
      else result = { status: code === 0 ? 'green' : 'red', code };
    }
  } finally {
    if (edited) git(copy, ['checkout', '-q', '--', edited]);
    const own = [...cfg.mutate.link, ...cfg.mutate.copy];
    let left = dirtyPaths(copy, own);
    if (left.length) {
      fs.writeSync(log, `# копия не чистая после отката: ${left.join(', ')} — восстанавливаю\n`);
      git(copy, ['checkout', '-q', '--', '.']);
      cleanCopy(copy, own);
      left = dirtyPaths(copy, own);
      if (left.length) { fs.closeSync(log); fail(`копия ${copy} не восстановилась: ${left.slice(0, 5).join(', ')}`); }
    }
    fs.closeSync(log);
  }
  result.log = logRel;
  result.time = Number(((Date.now() - t0) / 1000).toFixed(1));
  job.result = result;
  const ru = { killed: 'убит', survived: 'выжил', green: 'зелёный', red: 'красный', 'apply-error': `ошибка применения: ${result.note}` };
  say(`done ${job.id}${mutant ? '' : ` (${job.label})`} ${ru[result.status]}${result.timeout ? ' (таймаут)' : ''} slot=${slot} time=${result.time}s log=${logRel}`);
}

main().then(
  (code) => { if (!opts.dryRun && !opts.clean) say(`CODE=${code}`); process.exit(code); },
  (e) => {
    if (e instanceof UserError) process.stderr.write(`mutants: ${e.message}\n`);
    else process.stderr.write(`mutants: ${e.stack ?? e}\n`);
    killChildren();
    say('CODE=2');
    process.exit(2);
  },
);
